/* Limited direct execution. The "direct" is why it is fast: the process's
   own instructions run on the real CPU, at full speed, unsupervised. */
while (pc < end)
    execute(*pc++);            /* no OS involvement at all */

/* The "limited" is the whole trick. A privileged operation is not
   forbidden - it is unreachable except through one door. */
int fd = open("/tmp/log", O_WRONLY);

/* open() is a thin wrapper whose body is, in effect: */
set_syscall_number(SYS_open);  /* which door, chosen from a fixed list */
trap();                        /* hardware: save regs, raise privilege,
                                  jump to the trap table entry */
/* ... the kernel runs, then executes return-from-trap ... */
/* control resumes on the next line, back in user mode */
return fd;

/* Boot time, kernel mode: the OS arms the one thing that can take
   the CPU back from a process that never asks for anything. */
void boot(void) {
    init_trap_table();            /* where to jump on trap and on interrupt */
    start_timer(10 /* ms */);     /* fires whether the process likes it or not */
    run_first_process();          /* return-from-trap into user mode */
}

/* Every 10 ms, in the timer handler, already in kernel mode: */
void timer_interrupt(void) {
    /* the hardware has already pushed the running process's user
       registers onto that process's kernel stack and raised privilege */
    proc_t *next = schedule();
    if (next != current)
        switch_context(&current->context, &next->context);
    /* return-from-trap now pops next's user registers and drops to user mode */
}

/* switch_context is a dozen instructions of assembly: it saves the kernel
   registers of the outgoing process into its process structure and loads
   the incoming one's, stack pointer last. */

/* Two numbers, and they are not the same number. */
turnaround = completion - arrival;   /* how long the job took, end to end */
response   = first_run  - arrival;   /* how long before it felt alive */

/* FIFO. Three jobs arrive together: A needs 100, B and C need 10. */
/*   A: 0 -> 100     B: 100 -> 110     C: 110 -> 120                */
/*   turnaround 100, 110, 120  -> average 110                       */

/* SJF runs exactly the same three jobs in the other order.         */
/*   B: 0 -> 10      C: 10 -> 20       A: 20 -> 120                 */
/*   turnaround 10, 20, 120    -> average 50                        */

/* Nothing was made faster. The work is identical; only the queue changed. */

/* Round robin: slice the CPU instead of handing it over whole.        */
/*   Three 5 ms jobs, 1 ms quantum: A B C A B C A B C ...              */
/*   response   0,  1,  2 -> average  1   (SJF:  0,  5, 10 -> avg  5)  */
/*   turnaround 13, 14, 15 -> average 14   (SJF:  5, 10, 15 -> avg 10) */

/* MLFQ: guess a job's future from its past, then revise the guess. */
proc_t *schedule(void) {
    /* Rule 1: higher priority wins. Rule 2: equal priority round-robins. */
    for (int q = TOP; q >= 0; q--)
        if (!empty(queue[q]))
            return rr_next(queue[q]);
    return IDLE;
}

void on_tick(proc_t *p) {
    /* Rule 3 already put p in the top queue when it arrived, optimistically. */
    if (++p->used >= allotment[p->prio] && p->prio > 0)
        p->prio--;                    /* Rule 4: allotment spent, you sink */
    if (now % BOOST_PERIOD == 0)
        for_each_process(raise_to_top);  /* Rule 5: everybody back to the top */
}
